request.user_message:
Abstract the following semantic predicate cluster into exactly one reusable predicate.

Cluster ID:
ternary-005

Cluster Arity:
3

Cluster Members:
[
  {
    "name": "CHECKS_INPUT_INTEGRITY_WITHOUT_MODIFICATION",
    "definition": "The reasoning states the goal of confirming that protected elements — inputs, parameters, components, or artifacts outside the intended change set — remain unaltered, a non-mutating inspection action is performed for that purpose, and the resulting observation reports state information or a changed-element listing bearing on whether those elements are unchanged or changed only where explicitly permitted.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning text expressing the intention to confirm that the protected elements — inputs, parameters, components, or artifacts outside the intended change set — were not modified."
      },
      {
        "name": "inspection_action",
        "type": "action",
        "description": "The non-mutating action (listing, status query, checksum, read, or comparison) applied to those elements or to the change set."
      },
      {
        "name": "inspection_result",
        "type": "observation",
        "description": "The observation reporting metadata, checksums, contents, changed-file listings, or comparison outcomes relevant to whether the protected elements were altered."
      }
    ],
    "assertion_conditions": [
      "The reasoning states that preserving or confirming the unmodified state of the protected elements — inputs, parameters, components, or artifacts outside the intended change set — is the purpose of the check.",
      "The inspection action does not write to or otherwise alter the inspected elements.",
      "The observation reports metadata, checksums, contents, a changed-element listing, or comparison outcomes that bear on whether the protected elements are unchanged or changed only where explicitly permitted."
    ],
    "exclusion_conditions": [
      "The action modifies the inspected elements.",
      "The inspection serves solution production rather than confirming preservation.",
      "No observation reports the inspection's outcome.",
      "No protected element is identified as required to remain unchanged."
    ]
  },
  {
    "name": "VERIFIES_NEGATIVE_CONSTRAINT",
    "definition": "The reasoning specifies items, values, or conditions that must not appear in a result or state; an action checks that result or state for their absence; and the observation confirms that none of the specified items are present.",
    "parameters": [
      {
        "name": "exclusion_reasoning",
        "type": "reasoning",
        "description": "The reasoning identifying the specific items, values, or conditions that must not appear."
      },
      {
        "name": "negative_check_action",
        "type": "action",
        "description": "The action testing the result or state for absence of the specified items."
      },
      {
        "name": "check_observation",
        "type": "observation",
        "description": "The observation reporting the outcome of the absence check."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies at least one specific item, value, or condition that must not appear in the result or state.",
      "The action performs a check directed at the absence of those specified items rather than only at expected positive content.",
      "The observation reports that none of the specified items are present, confirming the negative constraint."
    ],
    "exclusion_conditions": [
      "The check only verifies positive presence or expected content.",
      "The observation reports that a specified item is present, or does not address the specified exclusions.",
      "No specific excluded item, value, or condition is stated in the reasoning.",
      "The absence check is not directed at the result or state under verification."
    ]
  }
]

