["CONFIGURES_EVENT_DRIVEN_AUTOMATION", "PREVENTS_SELF_CAUSED_ADVERSE_EFFECTS_THROUGH_CORRECTIVE_ACTION", "EVALUATES_CANDIDATE_AGAINST_ENUMERATED_CONSTRAINTS_OR_SCENARIOS", "RESOLVES_EVALUATED_CANDIDATE_ELEMENTS_TO_SINGLE_RESULT", "INTERPRETS_REQUIREMENTS_FOR_ACTION_ADMISSIBILITY", "INITIATES_DETACHED_ASYNCHRONOUS_EXECUTION", "REPORTS_ABSENT_OR_UNAVAILABLE_CAPABILITY", "IDENTIFIES_SPECIFIC_POTENTIAL_FAILURE_MODE", "ASSESSES_COMPETING_ACCOUNTS_OF_SAME_OBSERVATION", "ESTABLISHES_EVIDENCE_GROUNDED_TASK_OUTCOME_REFERENCE", "FORMULATES_STRUCTURED_OPERATIVE_ACCOUNT", "SPECIFIES_TARGET_LINKED_CONCRETE_MEANS", "GROUNDS_COMPUTATIONAL_ASSESSMENT_IN_QUANTITATIVE_ANALYSIS", "ANTICIPATES_PROSPECTIVE_VERIFICATION", "DELIMITS_MODIFICATION_AND_RESIDUAL_ARTIFACT_SCOPE", "IDENTIFIES_DEFICIENCY_OR_INCOMPLETENESS", "REPRODUCES_SPECIFIED_PROCEDURE_OR_OPERATION_ORDER", "IMPLEMENTS_LIMITATION_RESPONSIVE_ALTERNATIVE_APPROACH", "EXECUTES_REASONED_REMOVAL_OF_UNWANTED_STATE", "RESOLVES_CANDIDATE_STATUS_FROM_OBSERVED_EVIDENCE", "GROUNDS_REASONING_SPECIFICATION_IN_OBSERVED_ACTION_OR_STATE", "MATERIALIZES_SPECIFIED_CONTENT_IN_DESIGNATED_ARTIFACT", "INTERPRETS_PROBLEMATIC_OBSERVATION_FOR_UNDERSTANDING_OR_RESPONSE", "GROUNDS_CONSTRAINT_OR_JUDGMENT_IN_OBSERVED_EVIDENCE", "CONFIRMS_INTENDED_EFFECT_OR_REQUIRED_STATE_FROM_OBSERVED_RESULT", "PRESERVES_VERIFIED_SUBSTANCE_DURING_REPRESENTATIONAL_REVISION", "CONSTRAINT_DRIVEN_ARTIFACT_ELIMINATION_OR_REVISION", "GENERALIZES_INFERRED_RULE_BEYOND_OBSERVED_EXAMPLES", "RECONSTRUCTS_ANCESTRY_OR_DIVERGENCE_FROM_VERSION_IDENTIFIERS", "INTEGRATES_MULTIPLE_OBSERVATIONS_INTO_UNIFIED_REPRESENTATION", "DIRECTS_INVESTIGATIVE_FOCUS_FROM_OBSERVED_FEATURE", "INTERPRETS_OBSERVED_CONTENT_AS_TYPED_OR_STRUCTURED_INFORMATION", "DERIVES_GOVERNING_ARTIFACT_JUDGMENT_FROM_OBSERVED_CONTENT", "DISCRIMINATES_BENIGN_REFERENCE_OCCURRENCES_FROM_ACTUAL_TARGETS", "RECORDS_DURABLE_ARTIFACT_STATE_REFERENCE_FOR_COMPARISON_OR_HISTORY", "PERSISTS_VALIDATED_STATE_TO_AUTHORITATIVE_STORE", "DERIVES_CONCRETE_TARGET_LOCATION_FROM_OBSERVED_LAYOUT_METADATA", "RESOLVES_TASK_RELEVANT_PREREQUISITE_OR_ENVIRONMENT_STATE", "CONDUCTS_CONCERN_MOTIVATED_EVIDENCE_GATHERING", "IMPLEMENTS_REASONED_FAILURE_OR_RISK_RESPONSE_WITH_OBSERVED_EVIDENCE", "RECOVERS_UNUSABLE_CHECK_RESULT_VIA_METHOD_DIAGNOSIS_AND_ALTERNATIVE_RETRIEVAL"]

Read every member's complete definition, ordered parameters, assertion conditions, and exclusion conditions. Identify the common underlying behavioral mechanism and generate exactly one complete predicate following the system instructions. The new predicate must preserve the cluster arity. Use a unique predicate name that does not conflict with previously generated predicate names. Return only the complete five-field JSON predicate.

message.content:
{
  "name": "CONFIRMS_ABSENCE_OF_UNWANTED_STATE_OR_CONTENT",
  "definition": "The reasoning identifies a negative or preservation constraint on a target state or result: one or more protected elements, parameters, components, or artifacts must remain unaltered except for explicitly permitted changes, and/or specified items, values, or conditions must not appear. A non-mutating inspection or check action examines that target for the unwanted modification or excluded presence. The observation reports a result that confirms the unwanted state or content is absent, such as unchanged or permitted-change evidence from metadata, checksums, contents, listings, or comparisons, or an absence finding for the specified excluded items.",
  "parameters": [
    {
      "name": "negative_constraint_reasoning",
      "type": "reasoning",
      "description": "The reasoning identifying the negative or preservation constraint: protected elements that must remain unaltered except where explicitly permitted and/or specific items, values, or conditions that must not appear in the target state or result."
    },
    {
      "name": "nonmutating_inspection_action",
      "type": "action",
      "description": "The non-mutating action that inspects the target or result, using a listing, status query, checksum, read, comparison, or similar check to detect unwanted modifications or specified excluded items without altering the inspected elements."
    },
    {
      "name": "absence_confirmation_observation",
      "type": "observation",
      "description": "The observation reporting that the inspected target has not undergone unwanted modification or that none of the specified excluded items, values, or conditions are present, possibly including metadata, checksums, contents, change listings, comparison outcomes, or explicit absence findings."
    }
  ],
  "assertion_conditions": [
    "The reasoning identifies at least one negative or preservation constraint: protected elements outside an intended change set that must remain unaltered except where explicitly permitted, or at least one specific item, value, or condition that must not appear in the target state or result.",
    "The check action is non-mutating with respect to the inspected target and is directed at detecting the identified unwanted modification or excluded item rather than producing the solution or altering the target.",
    "The observation reports an outcome that confirms the identified unwanted state or content is absent, including unchanged or permitted-change evidence, or an explicit finding that none of the specified excluded items are present."
  ],
  "exclusion_conditions": [
    "The action writes to, deletes, or otherwise alters the inspected elements or target state.",
    "The reasoning identifies no protected element, permitted-change boundary, or specified item, value, or condition that must be absent.",
    "No observation reports the outcome of the inspection or absence check.",
    "The observation reports an unwanted modification or the presence of a specified excluded item, value, or condition rather than confirming its absence.",
    "The check addresses only positive expected content and does not evaluate the specified negative or preservation constraint.",
    "The inspection serves only to generate or transform a solution rather than to confirm the preservation or absence constraint."
  ]
}

